/// What x86::call_ext may run itself: every lifted function that is not
/// ext, and the platform models (same rule as harness.run_sparse).
pub fn dispatch_table() -> std::collections::HashMap<u32, fn(&mut dyn Mem, &mut Cpu)> {
    let ext: std::collections::HashSet<u32> = EXT.iter().copied().collect();
    let mut t: std::collections::HashMap<u32, fn(&mut dyn Mem, &mut Cpu)> =
        all().into_iter().filter(|(a, _)| !ext.contains(a)).collect();
    for &(a, _, f) in crate::platform::MODELS { t.insert(a, f); }
    t
}
